-- Add only the assigning player's name to the credential-protected context.
-- No celebrity text, new table, endpoint, grant, or change to existing round history.
create or replace function dock_celebrity.player(p_token text,p_round uuid,p_secret text) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('giver_name',case when r.phase='completed' then null else (select giver.name from dock_celebrity.entries assigned join dock_celebrity.players giver on giver.id=assigned.player_id where assigned.round_id=r.id and assigned.recipient_id=c.player_id) end,'recipient_name',case when r.phase='completed' then null else p.name end,'submitted',a.celebrity is not null,'position',a.position,'phase',r.phase,'number',r.number,'previous',(select jsonb_build_object('number',h.number,'position',last_entry.position,'placements',(select jsonb_agg(jsonb_build_object('name',previous_player.name,'position',previous_entry.position) order by previous_entry.position nulls last,previous_player.name) from dock_celebrity.entries previous_entry join dock_celebrity.players previous_player on previous_player.id=previous_entry.player_id where previous_entry.round_id=h.id)) from dock_celebrity.rounds h join dock_celebrity.entries last_entry on last_entry.round_id=h.id and last_entry.player_id=c.player_id where h.game_id=g.id and h.phase='completed' and h.number<r.number order by h.number desc limit 1),'placements',case when r.phase='completed' then (select jsonb_agg(jsonb_build_object('name',finished.name,'position',e.position) order by e.position) from dock_celebrity.entries e join dock_celebrity.players finished on finished.id=e.player_id where e.round_id=r.id) else null end)
 from dock_celebrity.games g join dock_celebrity.rounds r on r.game_id=g.id join dock_celebrity.claims c on c.round_id=r.id join dock_celebrity.entries a on a.round_id=r.id and a.player_id=c.player_id join dock_celebrity.players p on p.id=a.recipient_id
 where g.share_token=p_token and g.state='active' and r.id=p_round and c.secret=p_secret and (g.current_round=r.id or r.phase='completed');
$$;
